begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id,email) values('77100000-0000-4000-8000-000000000001','feed_audit_a@example.test'),('77100000-0000-4000-8000-000000000002','feed_audit_b@example.test');
select set_config('request.jwt.claim.sub','77100000-0000-4000-8000-000000000001',true);
select public.complete_onboarding('feed_audit_a','00000000-0000-4000-8000-000000000001','00000000-0000-4000-8000-000000000002','B1','UTC');
create temporary table photos(n integer,id uuid);
create function pg_temp.capture(day date) returns uuid language plpgsql as $$
declare c uuid;s public.submissions;o storage.objects;term uuid;
begin
 insert into public.daily_challenges(user_id,user_language_profile_id,created_at)
  select user_id,id,day::timestamp at time zone 'UTC' from public.user_language_profiles where user_id=auth.uid() returning id into c;
 select id into term from public.vocabulary_terms where language_id='00000000-0000-4000-8000-000000000002' and cefr_level='A2' order by id limit 1;
 insert into public.daily_challenge_words(daily_challenge_id,slot,cefr_level,vocabulary_term_id) values(c,'review','A2',term);
 perform private.assign_challenge_word(c,'target');perform private.assign_challenge_word(c,'stretch');
 s:=public.reserve_submission((select id from public.daily_challenge_words where daily_challenge_id=c and slot='review'));
 insert into storage.objects(bucket_id,name,owner_id,version,metadata) values('challenge-submissions',s.storage_path,s.user_id::text,'history-fixture','{"mimetype":"image/jpeg","size":100}') returning * into o;
 -- SQL metadata fixture only; real JPEG/Storage coverage is in the integration suite.
 perform public.attest_submission_photo(s.id,s.user_id,o.id,o.version,repeat('a',64),16,16);
 perform public.finalize_submission(s.id);return s.id;
end;
$$;
insert into photos values(1,pg_temp.capture('2026-08-01')),(2,pg_temp.capture('2026-08-02')),(3,pg_temp.capture('2026-08-03'));
select public.set_submission_visibility(id,'public') from photos;
alter table public.submissions disable trigger prepare_submission;
update public.submissions set submitted_at='2026-08-04T12:00:00.123456Z' where id in(select id from photos);
alter table public.submissions enable trigger prepare_submission;
create temporary table expected as select id,row_number() over(order by id desc) n from photos;
create temporary table ledger_before as select * from public.xp_events where user_id=auth.uid();
select set_config('request.jwt.claim.sub','77100000-0000-4000-8000-000000000002',true);
select public.complete_onboarding('feed_audit_b','00000000-0000-4000-8000-000000000001','00000000-0000-4000-8000-000000000002','B1','UTC');
create temporary table pages(n integer,payload jsonb);
grant select,insert on pages to authenticated;
grant select on photos,expected to authenticated;
set local role authenticated;
set local plan_cache_mode=force_generic_plan;
insert into pages values(1,public.get_discover_feed(page_size=>1));
insert into pages select 2,public.get_discover_feed((payload->'items'->0->>'submitted_at')::timestamptz,(payload->'items'->0->>'id')::uuid,1) from pages where n=1;
insert into pages select 3,public.get_discover_feed((payload->'items'->0->>'submitted_at')::timestamptz,(payload->'items'->0->>'id')::uuid,1) from pages where n=2;
select is((select array_agg(payload->'items'->0->>'id' order by n) from pages),(select array_agg(id::text order by n) from expected),'Every tied row appears exactly once across all keyset pages');
select is((select array_agg((payload->>'has_more')::boolean order by n) from pages),array[true,true,false],'Lookahead ends precisely at last eligible row');
select is(jsonb_array_length(public.get_discover_feed('2026-08-04T12:00:00.123455Z',gen_random_uuid(),24)->'items'),0,'One microsecond below tie excludes every row');
select is(jsonb_array_length(public.get_discover_feed('2026-08-04T12:00:00.123457Z',gen_random_uuid(),24)->'items'),3,'One microsecond above tie includes every row');
select throws_ok($$select public.get_discover_feed(page_size=>null)$$,'22023','invalid_feed_query','Null page bound denied');
select throws_ok($$select public.get_discover_feed(page_size=>-1)$$,'22023','invalid_feed_query','Negative page bound denied');
select throws_ok($$select public.get_discover_feed(before_time=>now())$$,'22023','invalid_feed_query','Time-only cursor denied');
select throws_ok($$select public.get_discover_feed('-infinity',gen_random_uuid(),1)$$,'22023','invalid_feed_query','Caller cannot inject internal sentinel');
select is((select count(*) from public.user_language_profiles where user_id='77100000-0000-4000-8000-000000000001'),0::bigint,'Feed does not grant private learning settings reads');
select is((select count(*) from public.xp_events where user_id='77100000-0000-4000-8000-000000000001'),0::bigint,'Public capture does not expose owner XP ledger');
select throws_ok($$select private.discover_target('77100000-0000-4000-8000-000000000001')$$,'42501',null,'Private viewer helper cannot be impersonated');
select throws_ok($$select public.begin_submission_deletion((select id from photos limit 1))$$,'42501',null,'Public visibility never grants deletion authority');
select is((select count(*) from public.profiles where id='77100000-0000-4000-8000-000000000001'),0::bigint,'Known submission does not expose owner profile');
reset role;
select set_config('request.jwt.claim.sub','77100000-0000-4000-8000-000000000001',true);
select public.set_submission_visibility((select id from expected where n=1),'private');
select set_config('request.jwt.claim.sub','77100000-0000-4000-8000-000000000002',true);
select is(public.get_discover_feed('2026-08-04T12:00:00.123456Z',(select id from expected where n=1),1)->'items'->0->>'id',(select id::text from expected where n=2),'Cursor stays usable after its row becomes private');
select is((select count(*) from public.get_discover_photo_targets(auth.uid(),'00000000-0000-4000-8000-000000000002',array[(select id from expected where n=1)])),0::bigint,'Renewal excludes a now-private cursor row');
update public.profiles set username='feed_renamed' where id='77100000-0000-4000-8000-000000000001';
select is((select username from public.get_discover_photo_targets(auth.uid(),'00000000-0000-4000-8000-000000000002',array[(select id from expected where n=2)])),'feed_renamed','Batch renewal reads the current public username');
-- Privileged corruption simulation stays inside this rolled-back test transaction.
set local session_replication_role=replica;
update storage.objects set version='stale-version' where name=(select storage_path from public.submissions where id=(select id from expected where n=2));
set local session_replication_role=origin;
select is((select count(*) from public.get_discover_photo_targets(auth.uid(),'00000000-0000-4000-8000-000000000002',array[(select id from expected where n=2)])),0::bigint,'Version-mismatched image cannot be signed');
select is(jsonb_array_length(public.get_discover_feed()->'items'),1,'Version mismatch excludes the feed item too');
update auth.users set banned_until=now()+interval '1 day' where id='77100000-0000-4000-8000-000000000001';
select is((select count(*) from public.get_discover_photo_targets(auth.uid(),'00000000-0000-4000-8000-000000000002',array[(select id from expected where n=3)])),0::bigint,'Banned owner public photo is not signable by another user');
update auth.users set banned_until=null,deleted_at=now() where id='77100000-0000-4000-8000-000000000001';
select is((select count(*) from public.get_discover_photo_targets(auth.uid(),'00000000-0000-4000-8000-000000000002',array[(select id from expected where n=3)])),0::bigint,'Deleted owner public photo is not signable by another user');
select throws_ok($$select public.get_discover_photo_targets(auth.uid(),'00000000-0000-4000-8000-000000000002',array[]::uuid[])$$,'22023','invalid_feed_query','Empty privileged signing batch denied');
select throws_ok($$select public.get_discover_photo_targets(auth.uid(),'00000000-0000-4000-8000-000000000002',array[null]::uuid[])$$,'22023','invalid_feed_query','Null privileged signing ID denied');
select throws_ok($$select public.get_discover_photo_targets(auth.uid(),'00000000-0000-4000-8000-000000000002',array[(select id from photos limit 1),(select id from photos limit 1)])$$,'22023','invalid_feed_query','Duplicate privileged signing IDs denied');
select ok(not has_function_privilege('anon','public.get_discover_photo_targets(uuid,uuid,uuid[])','execute') and not has_function_privilege('authenticated','public.get_discover_photo_targets(uuid,uuid,uuid[])','execute'),'Privileged signing lookup grants stay service only');
select ok((select prosecdef and proconfig @> array['search_path=""'] from pg_proc where oid='public.get_discover_photo_targets(uuid,uuid,uuid[])'::regprocedure),'Signer lookup has a fixed empty search path');
select is((select jsonb_agg(to_jsonb(e) order by id) from public.xp_events e where user_id='77100000-0000-4000-8000-000000000001'),(select jsonb_agg(to_jsonb(e) order by id) from ledger_before e),'Feed reads, visibility and signing do not change XP history');
select * from finish();
rollback;
